# -*- coding: utf-8 -*-
"""重建 XUnity.AutoTranslator 词典 _AutoGeneratedTranslations.txt。

    python tools/rebuild_at.py --csv docs/译本.csv
    python tools/rebuild_at.py --csv ... --baseline _AutoGeneratedTranslations.txt.bak_pre_v5

AT 层是非权威兜底层: 键集合 (英文) 取自 baseline, 值按 "精确 -> 模糊 -> 机械规范" 三级重填:
  1. 精确: 键去掉字面 \\n 后按 Norm 归一, 命中 CSV 英文原文 -> 直接用译文;
  2. 模糊: 折叠标点/引号/破折号/省略号差异后再比一次 (仅接受唯一解, 避免歧义覆盖);
  3. 机械: 都未命中时, 对 baseline 原值做标点规范化 (...... -> ……, -- -> ——,
     半角括号转全角, ! ? 转全角, 顿号按连接词判定改逗号)。

baseline 的默认值就是当前 AT 文件本身 —— 对同一译本重跑是幂等的, 这也是日常"换译本"的
正确用法: 键集合不变, 值整体刷新。只有在需要从更早的原点重建时才显式指定 --baseline。

真实换行写入前一律转义为字面 \\n, 因为 XUAT 按行解析该文件。
"""
import argparse
import csv
import os
import re
import shutil
import sys
from collections import defaultdict

TAG_RE = re.compile(r"<[/#a-zA-Z][^>]*>")
WS_RE = re.compile(r"\s+")
CJK_RE = re.compile(r"[一-鿿]")
NB = chr(92) + "n"   # 字面反斜杠 + n

# 同形异义: 裸词 Lebkuchen 在 AT 里是角色名牌, 取角色名「斯佩尔特」;
# 食品「姜饼」由 item_names 层与 ITM_F_N_08 承担。理由同 apply_translation.py。
NAME_OVERRIDE = {"Lebkuchen": "斯佩尔特"}

# 定名护栏, 理由同 apply_translation.py: AT 里同样有几千条英文串不在译本里,
# 旧译文会把错叫名写成真名。只换"串成别的角色名"的那个, 其余措辞不动。
NAME_GUARD = [
    # mercy 小写是"仁慈", 只有大写 Mercy 才是人名, 必须区分大小写。
    ("Rosmarine", "萝森玛琳", "萝丝玛琳", False),
    ("Rozenmarine", "萝丝玛琳", "萝森玛琳", False),
    ("Mercy", "梅西", "默茜", True),
    ("Macy", "默茜", "梅西", True),
]
NAME_GUARD_RE = [(re.compile(r"\b" + en + r"\b", 0 if cs else re.I), wrong, right)
                 for en, wrong, right, cs in NAME_GUARD]

# Missy 泛化成"小丫头", 短语级替换会误伤, 用整键覆盖。
KEY_OVERRIDE = {"Tell her what, Missy?": "告诉她什么呢，米茜？"}

# 游戏 TMP 不识别 wave / shake / incr, 会把标签当字面量显示; <size>/<color>/<sprite> 支持。
# 理由与 apply_translation.py 同一处。只剥中文值, AT 的英文键必须原样保留才能命中。
BAD_TAG_RE = re.compile(r"</?(?:wave|shake|incr)\b[^>]*>")


def clean_zh(s):
    return BAD_TAG_RE.sub("", s or "").strip()


def norm(s):
    return WS_RE.sub(" ", TAG_RE.sub("", s or "")).strip()


def fkey(s):
    s = s.replace(NB, " ")
    s = (s.replace("’", "'").replace("‘", "'")
          .replace("“", '"').replace("”", '"')
          .replace("—", "-").replace("–", "-").replace("…", "..."))
    return WS_RE.sub("", TAG_RE.sub("", s)).lower()


def mech(v):
    v = v.replace("......", "……").replace("--", "——")
    # 括号内容常带省略号/问号, 旧规则要求整段纯汉字才转换, 于是带标点的独白
    # 一直保留半角括号。这里放宽为"含汉字即可"。
    v = re.sub(r"\(([^()]*[一-鿿][^()]*)\)", r"（\1）", v)
    v = re.sub(r"(?<=[一-鿿])[:;]|[:;](?=[一-鿿])",
               lambda m: "：" if m.group(0) == ":" else "；", v)
    v = v.replace("!", "！").replace("?", "？")
    return re.sub(r"[ \t]+([！？])", r"\1", v)


def legacy_fix(k, s):
    if k in KEY_OVERRIDE:
        return KEY_OVERRIDE[k]
    for rx, wrong, right in NAME_GUARD_RE:
        if wrong in s and rx.search(k):
            s = s.replace(wrong, right)
    return s


def conv_du(text):
    out = []
    for i, ch in enumerate(text):
        if ch != "、":
            out.append(ch)
            continue
        prev = text[i - 1] if i > 0 else ""
        nxt = text[i + 1] if i + 1 < len(text) else ""
        if prev and prev == nxt:
            out.append("、")
            continue
        seg = re.split(r"[，。！？；…]", text[i + 1:])[0]
        out.append("、" if re.search(r"(和|与|及|以及|还有)", seg) and len(seg) <= 12 else "，")
    return "".join(out)


def esc(v):
    return v.replace("\r", "").replace("\n", NB)


def main():
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--csv", required=True)
    ap.add_argument("--live", default=None, help="游戏根目录; 默认取仓库内自带 AT")
    ap.add_argument("--baseline", default=None, help="键集合来源, 默认 = 当前 AT 文件")
    ap.add_argument("--backup-suffix", default=".bak_pre_rebuild")
    args = ap.parse_args()

    repo = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    at_dir = os.path.join(args.live, r"BepInEx\Translation\zh\Text") if args.live \
        else os.path.join(repo, "BepInEx", "Translation", "zh", "Text")
    dst = os.path.join(at_dir, "_AutoGeneratedTranslations.txt")
    src = args.baseline or dst

    if not os.path.exists(dst):
        sys.exit("找不到 AT 文件: " + dst)
    bck = dst + args.backup_suffix
    if not os.path.exists(bck):
        shutil.copy2(dst, bck)
        print("备份 " + os.path.basename(bck))

    rows = list(csv.DictReader(open(args.csv, encoding="utf-8-sig")))
    cols = rows[0].keys() if rows else []
    has_rev = "修订译文" in cols
    print("译本列集: %d 列%s" % (len(cols), " (旧 11 列格式, 以 修订译文 优先)" if has_rev else " (9 列格式)"))
    eff = lambda r: clean_zh(((r.get("修订译文") or "").strip() or r["中文译文"]) if has_rev else r["中文译文"])

    exact = {}
    fuzzy = defaultdict(set)
    for r in rows:
        en, zh = r["英文原文"], eff(r)
        if not en.strip() or not zh:
            continue
        exact.setdefault(norm(en.replace("\n", " ")), zh)
        exact.setdefault(norm(en), zh)
        exact.setdefault(norm(en.replace(NB, " ")), zh)
        fuzzy[fkey(en)].add(zh)
    fuzzy_u = {k: next(iter(v)) for k, v in fuzzy.items() if len(v) == 1}
    for k, v in NAME_OVERRIDE.items():
        exact[norm(k)] = v

    lines = open(src, "r", encoding="utf-8", newline="").read().split("\n")
    out = []
    n_exact = n_fuzzy = n_mech = n_keep = 0
    for line in lines:
        if "=" not in line:
            out.append(line)
            continue
        k, v = line.split("=", 1)
        cand = exact.get(norm(k.replace(NB, " ")))
        if cand is not None:
            n_exact += 1
        else:
            cand = fuzzy_u.get(fkey(k))
            if cand is not None:
                n_fuzzy += 1
        if cand is not None:
            nv = cand
        else:
            nv = mech(v) if CJK_RE.search(v) else v
            if "、" in nv:
                nv = conv_du(nv)
            nv = legacy_fix(k, nv)
            if nv != v:
                n_mech += 1
            else:
                n_keep += 1
        out.append(k + "=" + esc(nv))

    with open(dst, "w", encoding="utf-8", newline="") as f:
        f.write("\n".join(out))
    entries = [l for l in out if "=" in l]
    print("源行数 %d | 精确 %d | 模糊 %d | 机械改写 %d | 原样保留 %d"
          % (len(lines), n_exact, n_fuzzy, n_mech, n_keep))
    print("输出条目 %d -> %s" % (len(entries), dst))


if __name__ == "__main__":
    sys.exit(main())
